{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Sound Baths & VIP Day</title>
  <meta name="description" content="Immersive sound bath experiences, private sessions, and a VIP Day offering sensory restoration in {{CITY}}, {{STATE}}.">
  <link rel="stylesheet" href="assets/css/styles.css">
  <script defer src="assets/js/main.js"></script>
</head>
<body class="theme-bold">
  <header class="site-header">
    <div class="wrap">
      <a class="logo" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav" id="main-nav">
        <a href="events.html">Gatherings</a>
        <a href="private-sessions.html">Sessions</a>
        <a href="pricing.html">Tuition</a>
        <a href="about.html">The Circle</a>
        <a href="faq.html">Questions</a>
        <a href="book.html" class="accent">Reserve</a>
        <a href="contact.html">Connect</a>
      </nav>
      <button id="menu-toggle" aria-label="Menu" class="menu-toggle">☰</button>
    </div>
  </header>

  <main>
    <section class="hero" id="hero">
      <div class="pattern" aria-hidden="true"></div>
      <div class="wrap hero-inner">
        <div class="hero-copy">
          <h1 class="title">Deep resonant rest — curated sound baths for modern life</h1>
          <p class="lead">{{TAGLINE}}. A sensory, premium practice in {{CITY}}, {{STATE}} with intimate groups and bespoke 1:1 VIP Day experiences.</p>
          <div class="hero-actions">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="events.html">Upcoming gatherings</a>
          </div>
          <p class="micro">Facilitator: {{FACILITATOR_NAME}} • Venue: {{VENUE_NAME}}</p>
        </div>
        <aside class="hero-panel">
          <div class="panel-item">
            <h4>Next event</h4>
            <p id="next-event">{{NEXT_EVENT_DATE}}</p>
            <a class="btn small" href="events.html">See full calendar</a>
          </div>
          <div class="panel-item">
            <h4>Quick diagnostic</h4>
            <form id="diagnostic-form" class="diagnostic" aria-label="How are you feeling">
              <label><input type="radio" name="state" value="stressed"> Tension & restlessness</label>
              <label><input type="radio" name="state" value="sleepless"> Sleep latency</label>
              <label><input type="radio" name="state" value="flat"> Flat, low energy</label>
              <button type="button" id="diagnostic-btn" class="btn tiny">Custom suggestion</button>
            </form>
            <p id="diagnostic-suggestion" class="suggestion" aria-live="polite"></p>
          </div>
        </aside>
      </div>
    </section>

    <section class="diagnostic-section wrap" id="diagnostic">
      <h2>Where you are — and what helps</h2>
      <p class="section-lead">A practical guide to sensing what your nervous system needs. Answer the quick diagnostic above for an immediate micro-practice.</p>
      <div class="cards">
        <div class="card">
          <h3>Feeling wired?</h3>
          <p>Try 3:6 breathing for five minutes before the session to reset the sympathetic response. Salt water and quiet are allies.</p>
        </div>
        <div class="card">
          <h3>Disconnected?</h3>
          <p>Bring a small object to anchor intention. Use the silent moments in the journey to notice subtle shifts.</p>
        </div>
        <div class="card">
          <h3>Need sleep support?</h3>
          <p>Post-session integration includes a tailored sound pillow recording for home practice.</p>
        </div>
      </div>
    </section>

    <section class="plan wrap" id="plan">
      <h2>VIP Day — a focused reset</h2>
      <p class="section-lead">A full-day immersive for one or two people: intake, personalized sound journey, somatic coaching, and integration tools to carry the practice home.</p>
      <div class="plan-grid">
        <div class="plan-step">
          <h4>Pre-session consult</h4>
          <p>We map needs: sleep history, sensitivities, and desired outcomes.</p>
        </div>
        <div class="plan-step">
          <h4>Curated sound journey</h4>
          <p>Instruments selected: crystal bowls, gong, chimes, and monochord to create layered timbres.</p>
        </div>
        <div class="plan-step">
          <h4>Integration & practice</h4>
          <p>Personalized takeaways: micro-habit plan, recorded soundscape, and a follow-up session.</p>
        </div>
      </div>
      <p class="contra">Sessions are sensory-rich and generally safe; see our contraindications below.</p>
    </section>

    <section class="micro-habits wrap" id="micro_habits">
      <h2>Micro-habits — sustainable sensory practice</h2>
      <p class="section-lead">Small daily gestures that compound. Built for people with busy lives who want deep change.</p>
      <ul class="habits-list">
        <li><strong>1-minute bell:</strong> Ring a chime once on waking to orient attention.</li>
        <li><strong>Sound pause:</strong> 2 minutes of silence + breath before screens.</li>
        <li><strong>Evening tone:</strong> A 7-minute guided listening sequence before sleep.</li>
      </ul>
      <button class="btn small" id="habit-toggle">More tips</button>
      <div id="habit-more" class="hidden">
        <p>Rotate between binaural listening, gentle humming, and a five-minute abdominal breathing practice. Keep a simple log for two weeks.</p>
      </div>
    </section>

    <section class="safety wrap" id="safety">
      <h2>What to bring & safety</h2>
      <div class="safety-grid">
        <div>
          <h3>What to bring</h3>
          <ul>
            <li>Yoga mat or blanket</li>
            <li>Pillow and cozy layers</li>
            <li>Water bottle</li>
            <li>Eye mask or scarf</li>
          </ul>
        </div>
        <div>
          <h3>Contraindications</h3>
          <p>To keep experiences safe: consult before booking if you have a pacemaker, epilepsy, recent concussion, are pregnant without medical clearance, or have severe auditory sensitivity. We may adapt or recommend alternatives.</p>
        </div>
        <div>
          <h3>Typical flow</h3>
          <ol>
            <li>Arrival & settling — 10–15 mins</li>
            <li>Intention & grounding — 10 mins</li>
            <li>Main sound journey — 45–60 mins</li>
            <li>Integration & sharing — 15–20 mins</li>
            <li>Takeaways — recordings & micro practices</li>
          </ol>
        </div>
      </div>
    </section>

    <section class="pricing wrap" id="pricing">
      <h2>Pricing snapshot</h2>
      <p class="section-lead">Concise options. Full breakdown on the Tuition page.</p>
      <div class="pricing-cards">
        <div class="price-card">
          <h3>Group night</h3>
          <p class="price">$30–$50</p>
          <p>Small group gatherings with layered instruments like tuning forks and crystal bowls.</p>
          <a class="btn tiny" href="events.html">Book a spot</a>
        </div>
        <div class="price-card featured">
          <h3>VIP Day</h3>
          <p class="price">Starting $950</p>
          <p>Full-day bespoke experience with recordings and integration support.</p>
          <a class="btn tiny" href="book.html">Reserve VIP</a>
        </div>
        <div class="price-card">
          <h3>Private session</h3>
          <p class="price">$150</p>
          <p>1:1 or couples' sessions tailored with instruments such as the gong and chimes.</p>
          <a class="btn tiny" href="private-sessions.html">Details</a>
        </div>
      </div>
    </section>

    <section class="cta wrap" id="cta">
      <div class="cta-inner">
        <h2>Ready to experience refined sound?</h2>
        <p>Book a VIP Day or join our next gathering for an immediate sensory reset.</p>
        <a class="btn large primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <p class="contact">Questions? Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>.</p>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="wrap">
      <div class="footer-left">© <span id="year"></span> {{BUSINESS_NAME}} • {{CITY}}, {{STATE}}</div>
      <div class="footer-right"><a href="privacy.html">Privacy</a> <a href="contact.html">Contact</a></div>
    </div>
  </footer>
</body>
</html>"} 
