{"path":"assets/css/styles.css","content":"/* Bold playful theme — sensory-focused layout */
:root{
  --bg:#0f1720;
  --card:#0b1220;
  --accent:#ffd7a8;
  --accent-2:#8be6d6;
  --muted:#9aa6b2;
  --glass: rgba(255,255,255,0.04);
  --round:14px;
  --maxw:1100px;
}
*{box-sizing:border-box}
html,body{height:100%;margin:0;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial; background:linear-gradient(180deg,#061018 0%, #0b1220 70%); color:#e6eef3}
.wrap{max-width:var(--maxw);margin:0 auto;padding:28px}
.site-header{position:sticky;top:0;background:linear-gradient(180deg, rgba(6,10,14,0.6), rgba(6,10,14,0.3));backdrop-filter: blur(6px);z-index:40}
.site-header .wrap{display:flex;align-items:center;gap:16px}
.logo{font-weight:800;color:var(--accent);text-decoration:none;font-size:1.15rem}
.main-nav{margin-left:auto;display:flex;gap:12px}
.main-nav a{color:var(--muted);text-decoration:none;padding:8px 10px;border-radius:8px}
.main-nav a:hover{color:#fff}
.menu-toggle{display:none;background:none;border:0;color:var(--accent);font-size:1.3rem}

.hero{position:relative;padding:64px 0 40px}
.hero .pattern{position:absolute;inset:0;background-image:url('assets/img/pattern.svg');background-size:cover;opacity:0.12;mix-blend-mode:soft-light}
.hero-inner{display:flex;gap:28px;align-items:stretch}
.hero-copy{flex:1}
.title{font-size:2.2rem;margin:0 0 12px;line-height:1.02;color:#fff}
.lead{color:var(--muted);margin:0 0 18px}
.btn{display:inline-block;padding:10px 14px;border-radius:10px;text-decoration:none;font-weight:600}
.btn.primary{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#102423;box-shadow:0 6px 24px rgba(11,20,20,0.35)}
.btn.ghost{background:transparent;border:1px solid rgba(255,255,255,0.06);color:var(--muted)}
.btn.small{padding:8px 10px;font-size:.9rem}
.btn.tiny{padding:6px 8px;font-size:.85rem;border-radius:8px}
.hero-panel{width:320px;background:linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.01));border-radius:12px;padding:18px;backdrop-filter: blur(6px);box-shadow:inset 0 1px 0 rgba(255,255,255,0.02)}
.panel-item{margin-bottom:14px}
.panel-item h4{margin:0 0 8px;color:var(--accent)}
.micro{font-size:.85rem;color:var(--muted);margin-top:12px}

.diagnostic-section{padding:30px 0}
.cards{display:flex;gap:14px}
.card{flex:1;background:var(--card);padding:18px;border-radius:12px}
.card h3{margin-top:0;color:var(--accent-2)}

.plan{padding:30px 0}
.plan-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:16px}
.plan-step{background:var(--glass);padding:16px;border-radius:12px}
.plan-step h4{margin:0;color:var(--accent)}

.micro-habits{padding:30px 0}
.habits-list{list-style:none;padding:0}
.habits-list li{background:linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.01));padding:12px;margin:8px 0;border-radius:10px}
.hidden{display:none}

.safety{padding:30px 0}
.safety-grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:14px}
.safety-grid h3{color:var(--accent)}

.pricing{padding:30px 0}
.pricing-cards{display:flex;gap:12px}
.price-card{flex:1;background:linear-gradient(180deg, rgba(255,255,255,0.01), rgba(255,255,255,0.02));padding:16px;border-radius:12px}
.price-card.featured{box-shadow:0 12px 40px rgba(11,18,20,0.5);transform:scale(1.02)}
.price{font-size:1.3rem;color:var(--accent)}

.cta{padding:40px 0;text-align:center}
.cta-inner{background:linear-gradient(90deg, rgba(139,230,214,0.06), rgba(255,215,168,0.03));padding:28px;border-radius:16px}

.site-footer{border-top:1px solid rgba(255,255,255,0.02);padding:18px 0;margin-top:28px}
.site-footer .wrap{display:flex;justify-content:space-between;align-items:center}
.footer-left{color:var(--muted)}
.footer-right a{color:var(--muted);margin-left:12px;text-decoration:none}

@media (max-width:900px){
  .hero-inner{flex-direction:column}
  .hero-panel{width:100%}
  .main-nav{display:none}
  .menu-toggle{display:block;margin-left:auto}
  .cards{flex-direction:column}
  .plan-grid{grid-template-columns:1fr}
  .safety-grid{grid-template-columns:1fr}
  .pricing-cards{flex-direction:column}
}

/* subtle animated frequency line */
@keyframes floaty{0%{transform:translateY(0)}50%{transform:translateY(-8px)}100%{transform:translateY(0)}}
.hero-copy .title{animation:floaty 8s ease-in-out infinite}

/* accessibility focus */
a:focus,button:focus,input:focus{outline:2px dashed var(--accent);outline-offset:2px}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Insert current year
  var y = new Date().getFullYear();
  var el = document.getElementById('year'); if(el) el.textContent = y;

  // Toggle mobile menu
  var toggle = document.getElementById('menu-toggle');
  var nav = document.getElementById('main-nav');
  if(toggle && nav){
    toggle.addEventListener('click', function(){
      nav.classList.toggle('open');
      if(nav.classList.contains('open')){
        nav.style.display = 'flex';
        toggle.textContent = '✕';
      } else {
        nav.style.display = '';
        toggle.textContent = '☰';
      }
    });
  }

  // Diagnostic quick suggestion logic
  var diagBtn = document.getElementById('diagnostic-btn');
  if(diagBtn){
    diagBtn.addEventListener('click', function(){
      var form = document.getElementById('diagnostic-form');
      var sel = form.querySelector('input[name="state"]:checked');
      var out = document.getElementById('diagnostic-suggestion');
      if(!sel){ out.textContent = 'Select one option to get a tailored micro-practice.'; return; }
      var v = sel.value;
      var msg = '';
      if(v==='stressed') msg = 'Try a 4-7-8 breathing cycle pre-session and book a grounding spot near the back of the room.';
      if(v==='sleepless') msg = 'Ask for a recording after your session and commit to a 7-minute evening tone ritual for five nights.';
      if(v==='flat') msg = 'Start with humming for three minutes and a soft chime to scaffold emotional sensation.';
      out.textContent = msg;
    });
  }

  // Habit toggle
  var habitToggle = document.getElementById('habit-toggle');
  var habitMore = document.getElementById('habit-more');
  if(habitToggle && habitMore){
    habitToggle.addEventListener('click', function(){
      habitMore.classList.toggle('hidden');
      habitToggle.textContent = habitMore.classList.contains('hidden') ? 'More tips' : 'Hide tips';
    });
  }

  // Insert NEXT_EVENT_DATE placeholder into Next event card if present
  var next = document.getElementById('next-event');
  if(next){
    var raw = next.textContent.trim();
    if(raw.indexOf('{{NEXT_EVENT_DATE}}')>-1 || raw===''){
      // Friendly default if placeholder not replaced
      next.textContent = '{{NEXT_EVENT_DATE}}';
    }
  }

})();"} 
